import { constants } from 'node:fs';
import { link, mkdir, open, realpath, rm, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { getRequiredEnv } from '@/lib/env';

/**
 * Attachment files live under STORAGE_LOCAL_PATH (a host directory that is
 * never served statically). Keys are generated by the server; user input never
 * becomes part of a path. Every resolved path must stay inside the root, and
 * files are opened without following symlinks.
 *
 *   <root>/.quarantine/<attachment id>   uploaded, not yet cleared by the scanner
 *   <root>/<form type>/<form id>/<uuid>  cleared files
 */

export class StoragePathError extends Error {}

let rootCache: string | undefined;

export async function storageRoot(): Promise<string> {
  if (!rootCache) {
    const configured = path.resolve(getRequiredEnv('STORAGE_LOCAL_PATH'));
    await mkdir(configured, { recursive: true, mode: 0o700 });
    rootCache = await realpath(configured);
  }
  return rootCache;
}

/** For tests that switch STORAGE_LOCAL_PATH. */
export function __resetStorageRootForTests(): void {
  rootCache = undefined;
}

/** Resolves a stored key to an absolute path inside the root, or throws. */
export async function resolveKey(key: string): Promise<string> {
  if (
    typeof key !== 'string' ||
    key === '' ||
    key.length > 512 ||
    key.includes('\0') ||
    key.includes('\\') ||
    path.isAbsolute(key) ||
    key.split('/').some((segment) => segment === '..' || segment === '.' || segment === '')
  ) {
    throw new StoragePathError('invalid storage key');
  }
  const root = await storageRoot();
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new StoragePathError('storage key escapes root');
  // The directory chain must not leave the root through a symlink either.
  let parentReal: string;
  try {
    parentReal = await realpath(path.dirname(full));
  } catch {
    return full; // parent does not exist yet (writes create it below)
  }
  if (parentReal !== root && !parentReal.startsWith(root + path.sep)) {
    throw new StoragePathError('storage directory escapes root');
  }
  return full;
}

export function quarantineKey(attachmentId: string): string {
  return `.quarantine/${attachmentId}`;
}

/** Writes new bytes; fails if anything already exists at that key. */
export async function writeNew(key: string, bytes: Uint8Array): Promise<void> {
  const full = await resolveKey(key);
  await mkdir(path.dirname(full), { recursive: true, mode: 0o700 });
  await resolveKey(key); // re-check after creating directories
  await writeFile(full, bytes, { flag: 'wx', mode: 0o600 });
}

/**
 * Moves a file to a new key without ever overwriting: hard-link to the
 * destination (fails if it exists), then remove the source.
 */
export async function promote(fromKey: string, toKey: string): Promise<void> {
  const from = await resolveKey(fromKey);
  const to = await resolveKey(toKey);
  await mkdir(path.dirname(to), { recursive: true, mode: 0o700 });
  await resolveKey(toKey);
  await link(from, to);
  await unlink(from);
}

export async function readNoFollow(key: string): Promise<Buffer> {
  const full = await resolveKey(key);
  const handle = await open(full, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const stat = await handle.stat();
    if (!stat.isFile()) throw new StoragePathError('not a regular file');
    return await handle.readFile();
  } finally {
    await handle.close();
  }
}

export async function removeKey(key: string): Promise<void> {
  const full = await resolveKey(key);
  await rm(full, { force: true });
}

export async function readIfExists(key: string): Promise<Buffer | null> {
  try {
    return await readNoFollow(key);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
}

